const base = $input.first().json;
const rows = $('Carregar histórico chat').all();

const parseContent = (raw) => {
  if (raw == null) return '';
  let msg = raw;
  if (typeof msg === 'string') {
    try { msg = JSON.parse(msg); } catch { return msg.trim(); }
  }
  if (typeof msg === 'object') {
    return String(msg.content ?? msg.text ?? msg.kwargs?.content ?? '').trim();
  }
  return String(msg).trim();
};

const lines = rows
  .slice()
  .reverse()
  .map((item) => {
    const msg = item.json.message ?? item.json;
    const type = msg?.type ?? msg?.role ?? '';
    const content = parseContent(msg);
    if (!content) return null;
    const label = ['human', 'user', 'HumanMessage'].includes(type) ? 'Cliente' : 'Assistente';
    return `${label}: ${content}`;
  })
  .filter(Boolean);

let listaMensagens = base.listaMensagens ?? '';
if (lines.length) {
  listaMensagens = `--- Histórico recente (${lines.length} mensagens) ---\n${lines.join('\n')}\n--- Mensagem atual ---\n${listaMensagens}`;
}

return [{ json: { ...base, listaMensagens } }];

