const vars = $('Variáveis').first().json;
const edit = $('Edit Fields1').first().json;
const webhook = $('Webhook').first().json;
const sessionRow = $('SessionID').first().json;
const sdr = $input.first().json;

const mobile = vars.mobile;
const pushName = webhook?.body?.data?.pushName || '';
const mensagem = String(edit.listaMensagens || vars.mensagem || '').trim();
const sessionId = edit.sessionId || sessionRow?.sessionid || '';
const output = String(sdr.output ?? sdr.text ?? '').trim();

const emailMatch = mensagem.match(/[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}/i);
const email = emailMatch ? emailMatch[0].toLowerCase() : (sessionRow?.email || '');

let nome = sessionRow?.nome || pushName || '';
const nomeMatch = mensagem.match(/(?:me chamo|meu nome [eé]|sou (?:o|a))\s+([A-Za-zÀ-ú][A-Za-zÀ-ú\s]{1,48})/i);
if (nomeMatch?.[1]) nome = nomeMatch[1].trim();

let tipoPerfil = sessionRow?.tipo_perfil || '';
if (!tipoPerfil) {
  const lower = mensagem.toLowerCase();
  if (/\b(b2b|empresa|revend|loja|marceneir|arquitet)/i.test(lower)) tipoPerfil = 'B2B';
  else if (/\b(b2c|casa|apartamento|residencial|consumidor|lar)/i.test(lower)) tipoPerfil = 'B2C';
}

const now = new Date().toISOString();

return [{
  json: {
    telefone: mobile,
    nome,
    sessionid: sessionId,
    email: email || null,
    push_name: pushName,
    ultima_mensagem_cliente: mensagem,
    ultima_resposta_ia: output,
    ultimo_contato: now,
    updated_at: now,
    tipo_perfil: tipoPerfil || null,
    _cliente_existe: Boolean(sessionRow?.id)
  }
}];

